"use client";

import * as React from "react";
import { cn } from "./utils";
import { Slider as SliderPrimitive } from "./primitive-slider";

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  thumbLabels,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Root> & {
  thumbLabels?: string[];
}) {
  const _values = React.useMemo(
    () =>
      Array.isArray(value)
        ? value
        : Array.isArray(defaultValue)
          ? defaultValue
          : [min, max],
    [value, defaultValue, min, max],
  );

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn("roc-ui", className)}
      {...props}
    >
      <SliderPrimitive.Track data-slot="slider-track" className={cn("roc-ui")}>
        <SliderPrimitive.Range
          data-slot="slider-range"
          className={cn("roc-ui")}
        />
      </SliderPrimitive.Track>
      {Array.from({ length: _values.length }, (_, index) => (
        <SliderPrimitive.Thumb
          aria-label={
            thumbLabels?.[index] ??
            (_values.length === 1 ? props["aria-label"] : undefined)
          }
          data-slot="slider-thumb"
          key={index}
          className="roc-ui"
        />
      ))}
    </SliderPrimitive.Root>
  );
}

export { Slider };

import "./slider.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

"use client";
// ROC primitive: a draggable value or range. Behaviour from Base UI.
// Keeps ROC's markup (Track, Range and Thumbs as siblings) and adds the Control Base UI needs.
import * as React from "react";
import { Slider as Base } from "@base-ui/react/slider";

type RootProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange" | "dir"
> & {
  value?: number[];
  defaultValue?: number[];
  onValueChange?: (value: number[]) => void;
  /** Called when a drag or key press ends, with the final value. */
  onValueCommit?: (value: number[]) => void;
  min?: number;
  max?: number;
  step?: number;
  minStepsBetweenThumbs?: number;
  orientation?: "horizontal" | "vertical";
  disabled?: boolean;
  name?: string;
  form?: string;
  dir?: "ltr" | "rtl";
};

const asArray = (value: number | readonly number[]) =>
  Array.isArray(value) ? [...value] : [value as number];

type ThumbProps = Omit<React.ComponentProps<"div">, "ref"> & {
  index?: number;
  "aria-label"?: string;
  ref?: React.Ref<any>;
};

function Root({
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  minStepsBetweenThumbs,
  dir: _dir,
  children,
  ...props
}: RootProps) {
  // Base UI needs each thumb's index; shadcn infers it from order.
  let next = 0;
  const numbered = React.Children.map(children, (child) =>
    React.isValidElement(child) && child.type === Thumb
      ? React.cloneElement(child as React.ReactElement<ThumbProps>, { index: next++ })
      : child,
  );
  return (
    <Base.Root
      {...(props as object)}
      value={value}
      defaultValue={defaultValue}
      onValueChange={(v: number | readonly number[]) => onValueChange?.(asArray(v))}
      onValueCommitted={(v: number | readonly number[]) => onValueCommit?.(asArray(v))}
      minStepsBetweenValues={minStepsBetweenThumbs}
      thumbAlignment="edge"
      // A dragged thumb may cross the other; values stay sorted.
      thumbCollisionBehavior="swap"
    >
      <Base.Control data-slot="slider-control">{numbered}</Base.Control>
    </Base.Root>
  );
}

function Thumb({ "aria-label": label, ...props }: ThumbProps) {
  return (
    <Base.Thumb
      {...(props as object)}
      getAriaLabel={label ? () => label : undefined}
    />
  );
}

export const Slider = {
  Root,
  Track: Base.Track as React.ComponentType<Omit<React.ComponentProps<"div">, "ref">>,
  Range: Base.Indicator as React.ComponentType<Omit<React.ComponentProps<"div">, "ref">>,
  Thumb,
};

@import "./ui-base.css";
.roc-ui[data-slot="slider"] {
  display: flex;
  align-items: center;
  position: relative;
  width: 100%;
  height: 36px;
  touch-action: none;
  user-select: none;
}
.roc-ui[data-slot="slider-track"] {
  position: relative;
  flex-grow: 1;
  height: 4px;
  border-radius: 99px;
  background: var(--roc-line, #e2e2e2);
  overflow: hidden;
}
.roc-ui[data-slot="slider-range"] {
  position: absolute;
  height: 100%;
  background: var(--roc-ink, #252525);
}
.roc-ui[data-slot="slider-thumb"] {
  display: block;
  position: relative;
  width: 18px;
  height: 18px;
  border: 1px solid var(--roc-line, #bcbcbc);
  border-radius: 50%;
  background: var(--roc-paper, #fff);
  box-shadow: 0 1px 3px #0001;
}
.roc-ui[data-slot="slider-thumb"]::before {
  content: "";
  position: absolute;
  inset: -9px;
}
.roc-ui[data-slot="slider"][data-orientation="vertical"] {
  flex-direction: column;
  width: 36px;
  height: 180px;
}
.roc-ui[data-slot="slider-track"][data-orientation="vertical"] {
  width: 4px;
  height: 100%;
}
.roc-ui[data-slot="slider-range"][data-orientation="vertical"] {
  width: 100%;
}
/* Base UI nests the track and thumbs in a control that takes the pointer. */
.roc-ui[data-slot="slider"] > [data-slot="slider-control"] {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  width: 100%;
  height: 100%;
}
.roc-ui[data-slot="slider"][data-orientation="vertical"] > [data-slot="slider-control"] {
  flex-direction: column;
}
/* The focusable element is the range input inside the thumb. */
.roc-ui[data-slot="slider-thumb"]:has(input:focus-visible) {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
